export async function GET(request:Request){const store=await cookies();const bearer=request.headers.get('authorization')?.replace(/^Bearer\s+/i,'');const cookieValid=validSession(store.get(cookieName)?.value);const host=request.headers.get('host')||'';const previewMode=host.includes('localhost')||host.includes('127.0.0.1')||host.endsWith('.e2b.app')||host.endsWith('.arena.site');const developmentBearer=previewMode&&validSession(bearer);const authenticated=cookieValid||developmentBearer;return NextResponse.json({authenticated,email:authenticated?adminEmail:null},{status:authenticated?200:401})}
